import json,csv,statistics,collections
L=lambda p:{r['item_id']:r for r in map(json.loads,open(p))}
st=L('video_check/state.jsonl'); j=L('video_check/runs/jev.jsonl'); h=L('video_check/runs/haiku.jsonl'); c=L('video_check/runs/codex.jsonl')
key={r['item_id']:(r['label'],r['note']) for r in csv.DictReader(open('video_check/answer_key.csv'))}
fl=lambda r:r['contradiction']>=.5 or r['extra_detail']>=.5 or r['support']<=.5
dec=lambda r:not any(.35<=r[q]<=.65 for q in('support','contradiction','extra_detail'))
f=lambda r:'S%.2f C%.2f X%.2f'%(r['support'],r['contradiction'],r['extra_detail'])
print('FALSE ALARMS / jev flagged real:')
for i in sorted(st):
  if st[i]['kind']=='real' and fl(j[i]): print(i,key[i][0],f(j[i]),'dec' if dec(j[i]) else 'band','H',h[i]['answer'],'C',c[i]['answer'])
print('PARTLY:')
for i in sorted(st):
  if st[i]['kind']=='real' and key[i][0]=='partly': print(i,f(j[i]),'flag' if fl(j[i]) else 'noflag','dec' if dec(j[i]) else 'band','H',h[i]['answer'],'C',c[i]['answer'],'|',key[i][1][:90])
print('PLANTED misses / band:')
for i in sorted(st):
  k=st[i]['kind']
  if k!='real' and (not fl(j[i])): print('MISS',i,k,f(j[i]),h[i]['answer'],c[i]['answer'])
for who,d in (('haiku',h),('codex',c)):
  for k in ('real','wrong_locator','cross_video','negation','mechanism'):
    print(who,k,collections.Counter(d[i]['answer'] for i in st if st[i]['kind']==k and (k!='real' or key[i][0]=='supported')), 'partlykey' if k=='real' else '', collections.Counter(d[i]['answer'] for i in st if k=='real' and key[i][0]=='partly'))
# jev flags by kind on what triggered
for k in ('wrong_locator','cross_video','negation','mechanism','real'):
  ids=[i for i in st if st[i]['kind']==k]
  print(k,'meanS %.2f C %.2f X %.2f'%tuple(statistics.mean(j[i][q] for i in ids) for q in ('support','contradiction','extra_detail')), 'decisive',sum(dec(j[i]) for i in ids))
# band reasons
for k in ('negation','mechanism','real'):
  ids=[i for i in st if st[i]['kind']==k and not dec(j[i])]
  print(k,'in-band q counts',collections.Counter(q for i in ids for q in ('support','contradiction','extra_detail') if .35<=j[i][q]<=.65))
# latency
for who,d in (('jev',j),('haiku',h),('codex',c)):
  ms=sorted(r['ms'] for r in d.values()); print(who,'median',statistics.median(ms),'max',max(ms),'sum',sum(ms))
EOF

